sect3.programlisting:
#!/bin/sh # # psif - Imprime du PostScript ou du texte brut sur une imprimante PostScript # Version script; CECI N'EST PAS la version fournie avec lprps # Fichier /usr/local/libexec/psif #
IFS="" read -r first_line first_two_chars=`expr "$first_line" : '\(..\)'`
if [ "$first_two_chars" = "%!" ]; then # # Travail PostScript, l'imprimer. # echo "$first_line" && cat && printf "\004" && exit 0 exit 2 else # # Texte brut, le convertir, puis l'imprimer. # ( echo "$first_line"; cat ) | /usr/local/bin/textps && printf "\004" && exit 0 exit 2 fi

sect4.programlisting:
#!/bin/sh # # hpdf - Imprime des données DVI sur une imprimante HP/PCL # Fichier /usr/local/libexec/hpdf
PATH=/usr/local/bin:$PATH; export PATH
# # Définit une fonction de nettoyage de nos fichiers temporaires. Ils prennent place # dans le répertoire courant, qui sera le répertoire # de file d'attente # de l'imprimante. # cleanup() { rm -f hpdf$$.dvi }
# # Définit une fonction de gestion des erreurs fatales: affiche le message # d'erreur et retourne 2. Ce code d'erreur de 2 indique à LPD # de ne pas essayer de réimprimer le travail d'impression # fatal() { echo "$@" 1>&2 cleanup exit 2 }
# # Si l'utilisateur enlève le travail d'impression, LPD envoie SIGINT, donc # il faut capturer le signal SIGINT # (et quelques autres signaux) pour nettoyer après notre passage. # trap cleanup 1 2 15
# # Assurons-nous qu'il n'y ait pas conflit ce nom avec des fichiers existants. # cleanup
# # Lien du fichier DVI vers l'entrée standard (fichier à imprimer). # ln -s /dev/fd/0 hpdf$$.dvi || fatal "Cannot symlink /dev/fd/0"
# # Conversion LF = CR+LF # printf "\033&k2G" || fatal "Cannot initialize printer"
# # Conversion et impression. Le code de retour de dvilj2p ne semble # pas fiable: ignorons-le. # dvilj2p -M1 -q -e- dfhp$$.dvi
# # Nettoyage et sortie de la procédure # cleanup exit 0

sect3.programlisting:
#!/bin/sh # # psdf - filtre DVI vers imprimante PostScript # Fichier /usr/local/libexec/psdf # # Appelé par lpd quand l'utilisateur lance lpr -d #
orig_args="$@"
fail() { echo "$@" 1>&2 exit 2 }
while getopts "x:y:n:h:" option; do case $option in x|y) ;; # Ignore n) login=$OPTARG ;; h) host=$OPTARG ;; *) echo "LPD started `basename $0` wrong." 1>&2 exit 2 ;; esac done
[ "$login" ] || fail "Pas de nom d'utilisateur" [ "$host" ] || fail "PAs de nom de machine"
( /usr/local/libexec/make-ps-header $login $host "DVI File" /usr/local/bin/dvips -f ) | eval /usr/local/libexec/lprps $orig_args

#!/usr/bin/perl
#
#  netprint - Filtre texte pour imprimante connectée au réseau
#  Fichier /usr/local/libexec/netprint
#
$#ARGV eq 1 || die "Usage: $0 <printer-hostname> <port-number>";

$printer_host = $ARGV[0];
$printer_port = $ARGV[1];

require 'sys/socket.ph';

($ignore, $ignore, $protocol) = getprotobyname('tcp');
($ignore, $ignore, $ignore, $ignore, $address)
    = gethostbyname($printer_host);

$sockaddr = pack('S n a4 x8', &AF_INET, $printer_port, $address);

socket(PRINTER, &PF_INET, &SOCK_STREAM, $protocol)
    || die "Can't create TCP/IP stream socket: $!";
connect(PRINTER, $sockaddr) || die "Can't contact $printer_host: $!";
while (<STDIN>) { print PRINTER; }
exit 0;

